/* saleson.shop.cart.CartMapper.getCartAvailableInsertValidationCountForItemTypeByCartParam */
SELECT COUNT(*)
FROM OP_CART C
	INNER JOIN OP_ITEM I ON C.ITEM_ID = I.ITEM_ID






	AND I.ITEM_TYPE != (
		SELECT ITEM_TYPE FROM OP_ITEM WHERE ITEM_ID = #{itemId}
	)

/* saleson.shop.cart.CartMapper.getCartListBySessionId */
SELECT * FROM OP_CART
WHERE SESSION_ID = #{sessionId}
ORDER BY CART_ID DESC

/* saleson.shop.cart.CartMapper.getDuplicateCart */
SELECT *
FROM OP_CART



			USER_ID = #{userId}


			SESSION_ID = #{sessionId}



	AND ITEM_ID = #{itemId}


		AND OPTIONS = #{options}


	AND ADDITION_ITEM_FLAG = #{additionItemFlag}

ORDER BY CART_ID DESC

