/* saleson.shop.cart.CartMapper.insertCart */
INSERT INTO OP_CART (CART_ID, SESSION_ID, USER_ID, ITEM_ID, QUANTITY, OPTIONS, SHIPPING_PAYMENT_TYPE, SHIPPING_GROUP_CODE, ADDITION_ITEM_FLAG, PARENT_ITEM_ID, SET_ITEM_FLAG, CREATED_DATE, TEXT_OPTION)
VALUES (#{cartId}, #{sessionId}, #{userId}, #{itemId}, #{quantity}, #{options}, #{shippingPaymentType},#{shippingGroupCode}, #{additionItemFlag}, #{parentItemId}, #{setItemFlag}, , #{textOption})

/* saleson.shop.cart.CartMapper.insertCartSet */
INSERT INTO OP_CART_SET (CART_ID, ITEM_ID, QUANTITY, OPTIONS, PARENT_CART_ID, CREATED_DATE)
VALUES (#{cartId}, #{itemId}, #{quantity}, #{options}, #{parentCartId}, )

