/* saleson.shop.cart.CartMapper.updateQuantity */
UPDATE OP_CART
SET QUANTITY = #{quantity}

	CART_ID = #{cartId}


			AND USER_ID = #{userId}


			AND SESSION_ID = #{sessionId}

/* saleson.shop.cart.CartMapper.updateSetQuantity */
UPDATE OP_CART_SET
SET QUANTITY = #{quantity}

	PARENT_CART_ID = #{parentCartId}
	AND ITEM_ID = #{itemId}

/* saleson.shop.cart.CartMapper.updateUserIdByCart */
UPDATE OP_CART
SET USER_ID = #{userId},
	QUANTITY = #{quantity}
WHERE
	CART_ID = #{cartId}

